<?php
declare(strict_types=1);use ImAuthenticator\Security;use ImAuthenticator\Web;$services=require dirname(__DIR__).'/src/bootstrap.php';extract($services,EXTR_SKIP);$user=$auth->requireUser();$requiredActions->refreshAutomaticCompletions((int)$user['id']);$apps=$launcher->applications((int)$user['id']);$cards='';foreach($apps as $a){$cards.='<article class="app-card" draggable="true" data-app="'.(int)$a['id'].'"><a href="'.Web::e($a['url']).'"><div class="app-icon">'.Web::e(mb_strtoupper(mb_substr((string)$a['name'],0,1))).'</div><div><strong>'.Web::e($a['name']).'</strong><span>'.Web::e($a['status_message']?:'').'</span></div></a><button class="favorite" data-favorite="'.((bool)$a['favorite']?'1':'0').'">'.((bool)$a['favorite']?'★':'☆').'</button></article>';}$cards=$cards?:'<div class="empty">Nie masz obecnie dostępu do żadnej aplikacji.</div>';$pending=$requiredActions->pending((int)$user['id']);$required=$pending!==[]?'<div class="alert warning"><a href="/account/required-actions">Masz '.count($pending).' wymaganych akcji do wykonania.</a></div>':'';
$content='<div class="page-head"><div><h1>Moje aplikacje</h1><p>Launcher pokazuje tylko aplikacje, do których masz efektywny dostęp.</p></div></div>'.$required.'<div class="app-grid" id="launcher">'.$cards.'</div><script>(()=>{const root=document.getElementById("launcher");let drag=null;root?.addEventListener("dragstart",e=>{drag=e.target.closest("[data-app]")});root?.addEventListener("dragover",e=>{e.preventDefault();const t=e.target.closest("[data-app]");if(drag&&t&&drag!==t)root.insertBefore(drag,t)});root?.addEventListener("drop",async e=>{e.preventDefault();const order=[...root.querySelectorAll("[data-app]")].map((el,i)=>({application_id:+el.dataset.app,sort_order:i}));await fetch("/account/app-preferences",{method:"POST",headers:{"Content-Type":"application/json","X-CSRF-Token":"'.Web::e(Security::csrfToken()).'"},body:JSON.stringify({order})})});root?.addEventListener("click",async e=>{const b=e.target.closest(".favorite");if(!b)return;e.preventDefault();const card=b.closest("[data-app]"),favorite=b.dataset.favorite!=="1";const r=await fetch("/account/app-preferences",{method:"POST",headers:{"Content-Type":"application/json","X-CSRF-Token":"'.Web::e(Security::csrfToken()).'"},body:JSON.stringify({application_id:+card.dataset.app,favorite})});if(r.ok){b.dataset.favorite=favorite?"1":"0";b.textContent=favorite?"★":"☆"}})} )();</script>';Web::page('Moje aplikacje',$content,$user);
